-- JobBuddy: create every table by hand (EMPTY database only). Generated by
-- scripts/generate-init-sql.ts. Also records the migrations in the drizzle journal so the
-- app's own migrate step on startup knows they're already applied.
BEGIN;

-- 0000_init
CREATE TYPE "public"."user_status" AS ENUM('active', 'unfollowed');
CREATE TABLE "users" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"line_user_id" text NOT NULL,
	"display_name" text,
	"picture_url" text,
	"language" text,
	"status" "user_status" DEFAULT 'active' NOT NULL,
	"notify_interview_reminders" boolean DEFAULT true NOT NULL,
	"pdpa_consented_at" timestamp with time zone,
	"followed_at" timestamp with time zone,
	"unfollowed_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "users_line_user_id_unique" UNIQUE("line_user_id")
);

-- 0001_preferences_and_sessions
CREATE TYPE "public"."work_mode" AS ENUM('any', 'onsite', 'hybrid', 'remote');
CREATE TABLE "conversation_sessions" (
	"user_id" uuid PRIMARY KEY NOT NULL,
	"flow" text NOT NULL,
	"state" jsonb NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "job_preferences" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"positions" text[] NOT NULL,
	"locations" text[] DEFAULT '{}'::text[] NOT NULL,
	"work_mode" "work_mode" DEFAULT 'any' NOT NULL,
	"min_salary" integer,
	"excluded_keywords" text[] DEFAULT '{}'::text[] NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "job_preferences_user_id_unique" UNIQUE("user_id")
);
ALTER TABLE "conversation_sessions" ADD CONSTRAINT "conversation_sessions_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_preferences" ADD CONSTRAINT "job_preferences_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;

-- 0002_jobs
CREATE TYPE "public"."job_workplace" AS ENUM('onsite', 'hybrid', 'remote');
CREATE TYPE "public"."user_job_status" AS ENUM('saved', 'applied', 'hidden');
CREATE TABLE "jobs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"provider" text NOT NULL,
	"board" text NOT NULL,
	"external_id" text NOT NULL,
	"company" text NOT NULL,
	"title" text NOT NULL,
	"location" text NOT NULL,
	"department" text,
	"workplace" "job_workplace",
	"url" text NOT NULL,
	"posted_at" timestamp with time zone,
	"first_seen_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_seen_at" timestamp with time zone DEFAULT now() NOT NULL,
	"active" boolean DEFAULT true NOT NULL
);
CREATE TABLE "user_jobs" (
	"user_id" uuid NOT NULL,
	"job_id" uuid NOT NULL,
	"status" "user_job_status" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "user_jobs_user_id_job_id_pk" PRIMARY KEY("user_id","job_id")
);
ALTER TABLE "user_jobs" ADD CONSTRAINT "user_jobs_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "user_jobs" ADD CONSTRAINT "user_jobs_job_id_jobs_id_fk" FOREIGN KEY ("job_id") REFERENCES "public"."jobs"("id") ON DELETE cascade ON UPDATE no action;
CREATE UNIQUE INDEX "jobs_source_unique" ON "jobs" USING btree ("provider","board","external_id");
CREATE INDEX "jobs_active_idx" ON "jobs" USING btree ("active");

-- 0003_notes_and_stages
CREATE TYPE "public"."application_stage" AS ENUM('applied', 'contacted', 'interview', 'waiting', 'offer', 'rejected');
CREATE TABLE "job_notes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"job_id" uuid NOT NULL,
	"body" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "user_jobs" ADD COLUMN "stage" "application_stage";
ALTER TABLE "job_notes" ADD CONSTRAINT "job_notes_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "job_notes" ADD CONSTRAINT "job_notes_job_id_jobs_id_fk" FOREIGN KEY ("job_id") REFERENCES "public"."jobs"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "job_notes_user_job_idx" ON "job_notes" USING btree ("user_id","job_id");
UPDATE "user_jobs" SET "stage" = 'applied' WHERE "status" = 'applied';

-- 0004_interviews
CREATE TABLE "interviews" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"job_id" uuid NOT NULL,
	"starts_at" timestamp with time zone NOT NULL,
	"place" text,
	"scheduled_at" timestamp with time zone DEFAULT now() NOT NULL,
	"reminded_evening_at" timestamp with time zone,
	"reminded_soon_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "interviews" ADD CONSTRAINT "interviews_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "interviews" ADD CONSTRAINT "interviews_job_id_jobs_id_fk" FOREIGN KEY ("job_id") REFERENCES "public"."jobs"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "interviews_user_starts_idx" ON "interviews" USING btree ("user_id","starts_at");
CREATE INDEX "interviews_starts_idx" ON "interviews" USING btree ("starts_at");

-- 0005_stage_days_and_places
CREATE TABLE "geocodes" (
	"query" text PRIMARY KEY NOT NULL,
	"lat" double precision,
	"lng" double precision,
	"label" text,
	"resolved_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "user_places" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"label" text NOT NULL,
	"lat" double precision NOT NULL,
	"lng" double precision NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
ALTER TABLE "user_jobs" ADD COLUMN "stage_changed_at" timestamp with time zone;
ALTER TABLE "user_places" ADD CONSTRAINT "user_places_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
CREATE INDEX "user_places_user_idx" ON "user_places" USING btree ("user_id");
UPDATE "user_jobs" SET "stage_changed_at" = "updated_at" WHERE "stage" IS NOT NULL;

-- 0006_link_import_queue
CREATE TYPE "public"."link_import_outcome" AS ENUM('new', 'duplicate', 'invalid', 'failed');
CREATE TYPE "public"."link_import_status" AS ENUM('pending', 'working', 'done');
CREATE TABLE "link_import_batches" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"total" integer NOT NULL,
	"repeated" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"notified_at" timestamp with time zone
);
CREATE TABLE "link_imports" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"batch_id" uuid NOT NULL,
	"user_id" uuid NOT NULL,
	"url" text NOT NULL,
	"status" "link_import_status" DEFAULT 'pending' NOT NULL,
	"outcome" "link_import_outcome",
	"job_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"claimed_at" timestamp with time zone,
	"done_at" timestamp with time zone
);
ALTER TABLE "link_import_batches" ADD CONSTRAINT "link_import_batches_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "link_imports" ADD CONSTRAINT "link_imports_batch_id_link_import_batches_id_fk" FOREIGN KEY ("batch_id") REFERENCES "public"."link_import_batches"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "link_imports" ADD CONSTRAINT "link_imports_user_id_users_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."users"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "link_imports" ADD CONSTRAINT "link_imports_job_id_jobs_id_fk" FOREIGN KEY ("job_id") REFERENCES "public"."jobs"("id") ON DELETE set null ON UPDATE no action;
CREATE INDEX "link_import_batches_user_idx" ON "link_import_batches" USING btree ("user_id");
CREATE INDEX "link_imports_status_idx" ON "link_imports" USING btree ("status","created_at");
CREATE INDEX "link_imports_batch_idx" ON "link_imports" USING btree ("batch_id");
CREATE INDEX "link_imports_user_status_idx" ON "link_imports" USING btree ("user_id","status");

CREATE SCHEMA IF NOT EXISTS drizzle;
CREATE TABLE IF NOT EXISTS drizzle.__drizzle_migrations (
  id SERIAL PRIMARY KEY,
  hash text NOT NULL,
  created_at bigint
);
